package com.smart.ecommerce.config;
import java.util.Properties;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.*;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.mail.javamail.JavaMailSenderImpl;
@Configuration public class MailConfig{ @Bean JavaMailSender javaMailSender(@Value("${spring.mail.host:localhost}")String host,@Value("${spring.mail.port:25}")int port,@Value("${spring.mail.username:}")String username,@Value("${spring.mail.password:}")String password,@Value("${spring.mail.properties.mail.smtp.starttls.enable:false}")String tls){ JavaMailSenderImpl s=new JavaMailSenderImpl();s.setHost(host);s.setPort(port);s.setUsername(username);s.setPassword(password);Properties p=s.getJavaMailProperties();p.put("mail.smtp.auth",String.valueOf(!username.isBlank()));p.put("mail.smtp.starttls.enable",tls);return s;}}
